package app.ember.data

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test
import java.io.File
import java.io.RandomAccessFile
import java.nio.ByteBuffer
import java.security.MessageDigest

/**
 * Edits real M4B files generated by ffmpeg in CI (see ci/tag-test.sh), then restores them.
 * The edited copies are left in TEST_M4B_OUT for ffprobe/ffmpeg to double-check.
 */
class Mp4TagWriterTest {

    private val inDir = System.getenv("TEST_M4B_DIR")?.let { File(it) }
    private val outDir = System.getenv("TEST_M4B_OUT")?.let { File(it) }

    private class MemoryBackup : Mp4TagWriter.BackupStore {
        var info: String? = null
        var tail: ByteArray? = null
        override fun exists() = info != null
        override fun save(info: String, tail: ByteArray?) {
            this.info = info
            this.tail = tail
        }
        override fun info() = info
        override fun tail() = tail
        override fun clear() {
            info = null
            tail = null
        }
    }

    private fun sha(f: File) = MessageDigest.getInstance("SHA-256").digest(f.readBytes())

    private fun read(raf: RandomAccessFile) = Mp4ChapterParser.parse(object : Mp4ChapterParser.ByteSource {
        override val size: Long get() = raf.length()
        override fun read(buf: ByteBuffer, pos: Long) {
            var p = pos
            while (buf.hasRemaining()) {
                val n = raf.channel.read(buf, p)
                if (n <= 0) break
                p += n
            }
        }
    })

    private fun edit(file: File, backup: MemoryBackup, tags: Mp4TagWriter.Tags?, chapters: List<Pair<Long, String>>?, totalMs: Long, cover: ByteArray? = null): Mp4TagWriter.Result =
        RandomAccessFile(file, "rw").use { raf ->
            Mp4TagWriter.writeCore(raf.channel, raf.channel, backup, tags, chapters, totalMs, cover) {
                chapters == null || Mp4TagWriter.chaptersMatch(read(raf), chapters)
            }
        }

    private fun runScenario(name: String) {
        assumeTrue("Test files not generated", inDir != null && File(inDir, name).exists())
        val work = File(outDir, "work-$name").apply { parentFile?.mkdirs() }
        File(inDir, name).copyTo(work, overwrite = true)
        val original = sha(work)
        val originalChapters = RandomAccessFile(work, "r").use { read(it) }
        assertEquals("$name: ffmpeg should have written 3 chapters", 3, originalChapters.size)
        val totalMs = 180_000L
        val backup = MemoryBackup()

        // Edit 1: new tags and a different number of chapters.
        val ch1 = listOf(0L to "Prologue: The Ember", 30_000L to "Part One — Ashes", 95_000L to "Part Two", 150_000L to "Épilogue")
        val cover = File(inDir, "cover.jpg").takeIf { it.exists() }?.readBytes()
        val r1 = edit(work, backup, Mp4TagWriter.Tags("Edited Title", "New Author", "A Narrator", "A description."), ch1, totalMs, cover)
        assertTrue("$name edit 1: $r1", r1 is Mp4TagWriter.Result.Ok)
        val after1 = RandomAccessFile(work, "r").use { read(it) }
        assertEquals(ch1.map { it.second }, after1.map { it.title })

        // Edit 2: the index is now at the end, so it's rewritten in place.
        val ch2 = listOf(0L to "One", 90_000L to "Two")
        val r2 = edit(work, backup, Mp4TagWriter.Tags("Second Title", "New Author", "A Narrator", ""), ch2, totalMs)
        assertTrue("$name edit 2: $r2", r2 is Mp4TagWriter.Result.Ok)
        assertEquals(listOf("One", "Two"), RandomAccessFile(work, "r").use { read(it) }.map { it.title })

        // Keep a copy of the edited file for ffprobe.
        work.copyTo(File(outDir, "edited-$name"), overwrite = true)

        // A failed check must leave the file untouched.
        val before = sha(work)
        val r3 = RandomAccessFile(work, "rw").use { raf ->
            Mp4TagWriter.writeCore(raf.channel, raf.channel, backup, null, listOf(0L to "Nope"), totalMs) { false }
        }
        assertTrue(r3 is Mp4TagWriter.Result.Failed)
        assertArrayEquals("$name: rollback should restore the previous bytes", before, sha(work))

        // Restore original: byte-for-byte identical.
        val r4 = RandomAccessFile(work, "rw").use { raf -> Mp4TagWriter.restoreCore(raf.channel, backup) }
        assertTrue("$name restore: $r4", r4 is Mp4TagWriter.Result.Ok)
        assertArrayEquals("$name: restore should give back the original file", original, sha(work))
    }

    @Test fun moovAtEnd() = runScenario("end.m4b")

    @Test fun moovAtFront() = runScenario("front.m4b")
}
